static int[,] RotateClockwise(int[,] matrix)
{
    int n = matrix.GetLength(0);
    int[,] result = new int[n, n];
    for (int row = 0; row < n; row++)
    {
        for (int col = 0; col < n; col++)
        {
            result[col, n - 1 - row] = matrix[row, col];
        }
    }
    return result;
}
